GF_Err hex_string_to_bin128(const char *string, bin128 value) {
    if (!string) {
        return GF_BAD_PARAM;
    }

    const char *ptr = string;
    if (*ptr == '0' && *(ptr + 1) == 'x') {
        ptr += 2;
    }

    size_t len = 0;
    while (ptr[len] != '\0') {
        len++;
    }

    if (len % 2 != 0) {
        return GF_BAD_PARAM;
    }

    unsigned int byte_count = len / 2;
    if (byte_count > 16) {
        return GF_BAD_PARAM;
    }

    for (int i = 0; i < byte_count; i++) {
        char byte_str[3] = { ptr[2 * i], ptr[2 * i + 1], '\0' };
        char *end;
        unsigned int nibble = strtoul(byte_str, &end, 16);
        if (*end != '\0') {
            return GF_BAD_PARAM;
        }
        value[i] = nibble;
    }

    for (int i = byte_count; i < 16; i++) {
        value[i] = 0;
    }

    return GF_OK;
}

