GF_Err parse_hex_to_bin128(const char *string, bin128 value)
{
    const char *ptr = string;
    char *end;
    int i, len;

    if (!string || !value) {
        return GF_BAD_PARAM;
    }

    // Check for optional "0x" prefix
    if (ptr[0] == '0' && (ptr[1] == 'x' || ptr[1] == 'X')) {
        ptr += 2;
    }

    // Calculate the length of the hex string
    len = (int)strlen(ptr);

    // Hex string must have even length and not exceed 32 chars (16 bytes)
    if (len % 2 || len > 32) {
        return GF_BAD_PARAM;
    }

    // Initialize output to zero
    for (i = 0; i < 16; i++) {
        value[i] = 0;
    }

    // Process the string in pairs
    for (i = 0; i < len / 2; i++) {
        unsigned int byte;

        if (i >= 16) {
            return GF_BAD_PARAM;
        }

        byte = (unsigned int)strtoul(ptr, &end, 16);

        if (end != ptr + 2 || byte > 255) {
            return GF_BAD_PARAM;
        }

        value[i] = (uint8_t)byte;
        ptr += 2;
    }

    // The result must have exactly 16 bytes
    if (i != 16) {
        return GF_BAD_PARAM;
    }

    return GF_OK;
}

GF_Err ParseHex128(const char *string, bin128 value) {
    if (!string || !value) return GF_BAD_PARAM;

    const char *hex_digits = "0123456789abcdefABCDEF";
    const char *ptr = string;
    int length = 0;

    // Check for "0x" prefix
    if (ptr[0] == '0' && (ptr[1] == 'x' || ptr[1] == 'X')) {
        ptr += 2;
    }

    // Determine length of the string
    while (strchr(hex_digits, *ptr)) {
        ptr++;
        length++;
    }

    // Validate that length is even and up to 32 characters (16 bytes)
    if (length % 2 != 0 || length > 32) {
        return GF_BAD_PARAM;
    }

    // Adjust length to bytes
    length /= 2;

    // Parse each pair of hex digits
    ptr = string;
    if (string[0] == '0' && (string[1] == 'x' || string[1] == 'X')) {
        ptr += 2;
    }

    for (int i = 0; i < length; i++) {
        unsigned char byte = 0;
        int nibble;

        for (int j = 0; j < 2; j++) {
            char c = *ptr++;
            if (!strchr(hex_digits, c)) {
                return GF_BAD_PARAM;
            }
            nibble = (c >= '0' && c <= '9') ? c - '0' :
                     (c >= 'a' && c <= 'f') ? c - 'a' + 10 :
                     (c >= 'A' && c <= 'F') ? c - 'A' + 10 : 0;

            byte = (byte << 4) | nibble;
        }

        value[i] = byte;
    }

    // Make sure exactly 16 bytes are parsed
    if (length != 16) {
        return GF_BAD_PARAM;
    }

    return GF_OK;
}

